import { describe, it, expect } from 'vitest'
import { create } from '@react-three/test-renderer'
import * as THREE from 'three'
import { SolarSystem } from '../src/SolarSystem.jsx'

const DELTA = 1 / 60
const FRAMES = 120 // 2 simulated seconds

function countMeshes(root) {
  let count = 0
  root.traverse((obj) => {
    if (obj.isMesh) count += 1
  })
  return count
}

describe('<SolarSystem />', () => {
  it('advances pivots by the correct angles over 2 simulated seconds at speed 1', async () => {
    const renderer = await create(<SolarSystem speed={1} />)
    await renderer.advanceFrames(FRAMES, DELTA)

    const pivotA = renderer.scene.getObjectByName('pivot-a')
    const pivotB = renderer.scene.getObjectByName('pivot-b')

    expect(pivotA).toBeDefined()
    expect(pivotB).toBeDefined()

    // period 4s -> half a revolution in 2s
    expect(pivotA.rotation.y).toBeCloseTo(Math.PI, 2)
    expect(Math.abs(pivotA.rotation.y - Math.PI)).toBeLessThan(5e-2)

    // period 10s -> 2/10 of a revolution in 2s
    expect(Math.abs(pivotB.rotation.y - (2 * Math.PI) / 5)).toBeLessThan(5e-2)
  })

  it('keeps planets on their orbit radii after advancing frames', async () => {
    const renderer = await create(<SolarSystem speed={1} />)
    await renderer.advanceFrames(FRAMES, DELTA)

    renderer.scene.updateMatrixWorld(true)

    const planetA = renderer.scene.getObjectByName('pivot-a-planet')
    const planetB = renderer.scene.getObjectByName('pivot-b-planet')

    const posA = new THREE.Vector3()
    const posB = new THREE.Vector3()
    planetA.getWorldPosition(posA)
    planetB.getWorldPosition(posB)

    expect(posA.length()).toBeCloseTo(3, 6)
    expect(Math.abs(posA.length() - 3)).toBeLessThan(1e-6)

    expect(posB.length()).toBeCloseTo(5, 6)
    expect(Math.abs(posB.length() - 5)).toBeLessThan(1e-6)
  })

  it('doubles angular advance when speed is 2', async () => {
    const base = await create(<SolarSystem speed={1} />)
    await base.advanceFrames(FRAMES, DELTA)

    const doubled = await create(<SolarSystem speed={2} />)
    await doubled.advanceFrames(FRAMES, DELTA)

    const a1 = base.scene.getObjectByName('pivot-a').rotation.y
    const b1 = base.scene.getObjectByName('pivot-b').rotation.y
    const a2 = doubled.scene.getObjectByName('pivot-a').rotation.y
    const b2 = doubled.scene.getObjectByName('pivot-b').rotation.y

    expect(a2).toBeCloseTo(a1 * 2, 5)
    expect(b2).toBeCloseTo(b1 * 2, 5)

    // 2 simulated seconds at speed 2 == 4 seconds of rotation
    expect(a2).toBeCloseTo(2 * Math.PI, 2)
    expect(Math.abs(a2 - 2 * Math.PI)).toBeLessThan(5e-2)
    expect(Math.abs(b2 - (4 * Math.PI) / 5)).toBeLessThan(5e-2)
  })

  it('contains exactly 3 meshes', async () => {
    const renderer = await create(<SolarSystem speed={1} />)
    expect(countMeshes(renderer.scene)).toBe(3)
  })
})

