import { useRef } from 'react'
import { useFrame } from '@react-three/fiber'

const TWO_PI = Math.PI * 2

function Planet({ name, radius, period, speed }) {
  const pivot = useRef()

  useFrame((_, delta) => {
    if (pivot.current) {
      pivot.current.rotation.y += (TWO_PI / period) * speed * delta
    }
  })

  return (
    <object3D ref={pivot} name={`pivot-${name}`}>
      <mesh name={`pivot-${name}-planet`} position={[radius, 0, 0]}>
        <sphereGeometry args={[0.4, 32, 32]} />
        <meshStandardMaterial />
      </mesh>
    </object3D>
  )
}

export function SolarSystem({ speed = 1 }) {
  return (
    <>
      <mesh name="sun">
        <sphereGeometry args={[1, 32, 32]} />
        <meshStandardMaterial color="yellow" />
      </mesh>
      <Planet name="a" radius={3} period={4} speed={speed} />
      <Planet name="b" radius={5} period={10} speed={speed} />
    </>
  )
}

export default SolarSystem

